## code Assisted with basic coding tools to convert MP3 to .OGG Audio Files
from pydub import AudioSegment
import os

APV=os.getcwd()
def convert_wav_to_ogg(input_folder,output_folder,quality=5):
	if not os.path.exists(output_folder):
		os.makedirs(output_folder)
	for file_name in os.listdir(input_folder):
		if file_name.endswith('.mp3'):
			input_path=os.path.join(input_folder,file_name)
			output_path=os.path.join(output_folder,file_name.replace('.mp3','.ogg'))
			try:
				audio=AudioSegment.from_mp3(input_path)
				audio.export(output_path,format="ogg",codec="libvorbis",bitrate="{}k".format(quality*16))
				print("Convert Audio: {} -> {}".format(file_name, output_path))
			except Exception as e:
				print("converting cancel: {} #{}".format(file_name, e))
input_folder=APV+'/mp3_folder'
output_folder=APV+'/ogg_folder'
convert_wav_to_ogg(input_folder,output_folder)

# 快排
def quick_sort(arr1):
    if len(arr1) < 2:
        return arr1
    else:
        pivot = arr1[0]
        less = [i for i in arr1[1:] if i < pivot]
        greater = [j for j in arr1[1:] if j >= pivot]
        return quick_sort(less) + [pivot] + quick_sort(greater)

# 归并
def merge_sort(arr1):
    if len(arr1) < 2:
        return arr1
    half = int(len(arr1) / 2)
    left_arr1 = merge_sort(arr1[:half])
    right_arr1 = merge_sort(arr1[half:])
    return merge(left_arr1, right_arr1)

def merge(left, right):
    result = []
    while left and right:
        result.append(left.pop(0) if left[0] <= right[0] else right.pop(0))
    # while left:
        # result.append(left.pop(0))
    result.extend(left)
    result.extend(right)
    # while right:
        # result.append(right.pop(0))
    return result


# 希尔
def shell_sort(relist):
    n = len(relist)
    gap = int(n / 2)  # 初始步长
    while gap > 0:
        for i in range(gap, n):
            relist[:i] = insertSort(relist[:i])
            print(relist)
        gap = int(gap / 2)  # 得到新的步长

    return relist


# 插入
def insert_sort(arr1):
    temp = [arr1[0]]
    arr1 = arr1[1:]
    while arr1:
        for j in range(len(temp)):
            if temp[j] > arr1[0]:
                temp.insert(j, arr1[0])
                break
        else:
            temp.insert(len(temp), arr1[0])
        arr1.pop(0)
    return temp

def insertSort(relist):
    len_ = len(relist)
    for i in range(1,len_):
        for j in range(i):
            if relist[i] < relist[j]:
                relist.insert(j,relist[i])  # 首先碰到第一个比自己大的数字，赶紧刹车，停在那，所以选择insert
                relist.pop(i+1)  # 因为前面的insert操作，所以后面位数+1，这个位置的数已经insert到前面去了，所以pop弹出
                break
    return relist

# 冒泡
def bubble_sort(arr1):
    for i in range(len(arr1)):
        for j  in range(len(arr1[1:])):
            if arr1[i] < arr1[j]:
                arr1[i], arr1[j] = arr1[j], arr1[i]
    return arr1

print(merge_sort([1,7,6, 8,22,6,77,11, 66, 14]))

"""
Hangman example Assisted with basic coding tools, 2024
"""

import random


def select_word():
    word_list = ["apple", "banana", "cherry", "date", "elderberry", "fig", "grape", "honeydew", "imbe", "jackfruit"]
    return random.choice(word_list)


def update_word(word, guessed_letters):
    masked_word = ""
    for letter in word:
        if letter in guessed_letters:
            masked_word += letter
        else:
            masked_word += "_"
    return masked_word


def hangman():
    tries = 6
    word = select_word()
    guessed_letters = []

    print("Welcome to Hangman!")
    print("Guess the letters of the word. You have 6 tries.")

    while tries > 0:
        print("\nWord:", update_word(word, guessed_letters))
        print("Tries remaining:", tries)

        guess = input("Enter a letter: ").lower()

        if guess in guessed_letters:
            print("You already guessed that letter. Try again.")
            continue

        guessed_letters.append(guess)

        if guess not in word:
            tries -= 1
            print("Incorrect guess!")

            if tries == 0:
                print("You lost! The word was:", word)
        else:
            masked_word = update_word(word, guessed_letters)
            if masked_word == word:
                print("Congratulations! You won!")
                break

    play_again = input("Do you want to play again? (yes/no): ").lower()
    if play_again == "yes":
        hangman()
    else:
        print("Thank you for playing Hangman!")


hangman()

import requests
