def ballot_with_goods(
    driver: WebDriver, with_goods: bool = False, is_pair: bool = False
) -> None:
    if with_goods:
        box_text = "グッズ付き　-----"
    else:
        box_text = "グッズなし　-----"

    ticket_option = WebDriverWait(driver, 10).until(
