@dispatcher.add_method
def create_raw_tx(vins, vouts):
    try:
        vins = json.loads(vins)
        vouts = json.loads(vouts)
        return Transaction.fromJSON({'vins': vins, 'vouts': vouts}).toJSON()

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def sign_raw_tx(tx, idx, pk):
    try:
        idx = int(idx)
        tx = Transaction.fromJSON(json.loads(tx))
        signed_tx = mutils.sign_tx(tx, idx, pk)
        return signed_tx.toJSON()

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def get_tx(txid):
    txid = str(txid)
    if txid in global_txs:
        return global_txs[txid].toJSON()
    return {'error': 'txid not found'}


@dispatcher.add_method
def send_raw_tx(tx):
    global global_best_block, global_txs, global_utxos

    try:
        # Original tx
        _tx_og = copy.deepcopy(tx)

        # Create new tx from the json dump
        tx = Transaction.fromJSON(json.loads(tx))

        # If is new tx then add it to block
        if tx.txid not in global_txs:
            # Add tx to global best block
            global_best_block, global_txs, global_utxos = mutils.add_tx_to_block(
                tx, global_best_block, global_txs, global_utxos
            )

            print('[INFO] txid {} added to block {}'.format(
                tx.txid, global_best_block.height))

            # Broadcast transaction to connected nodes
            for node in global_nodes:
                try:
                    misocoin_cli('send_raw_tx', [
                                 json.dumps(tx.toJSON())], **node)
                except Exception as e:
                    pass

        return {'txid': tx.txid}

    except Exception as e:
        return {'error': str(e)}


@dispatcher.add_method
def receive_mined_block(block_str):
    global global_best_block, global_blockchain

    try:
        block = Block.fromJSON(json.loads(block_str))
        add_to_blockchain(block)
        return {'success': True}

    except Exception as e:
        return {'error': str(e)}


@Request.application
def misocoin_app(request):
    response = JSONRPCResponseManager.handle(request.data, dispatcher)
    return Response(response.json, mimetype='application/json')


# Block management
# Handles the mining of blocks, as well as the automatic adjusting of difficulty
def block_management():
    global global_best_block, global_blockchain, global_txs, global_utxos, global_difficulty

    while True:
        time.sleep(10)

        try:
            last_mined_time = global_blockchain[-1].timestamp
        except:
            last_mined_time = genesis_epoch

        # Auto mine
        # if 30 seconds has passed since last mining
        if (time.time() - last_mined_time > 30):
            # Mine block
            mined_block = mine_block(global_best_block, account_address)

            if (mined_block.coinbase.reward_address == account_address):
                print('[SUCCESS] You found the nonce for block {}'.format(
                    mined_block.height))

            # Broadcast block to nodes
            mined_block_str = json.dumps(mined_block.toJSON())
            for node in global_nodes:
                # If node['host'] is in black list then continue
                if node['host'] in global_blacklisted_nodes:
                    continue

                try:
                    misocoin_cli('receive_mined_block', [
                                 mined_block_str], **node)

                except:
                    pass


@dispatcher.add_method
def init_connection(host, port):
    global global_nodes

    # Check if we already have the node,
    # add it if we dont
    has_node = reduce(lambda x, y: x and (
        y['host'] == host), global_nodes, False)
    if not has_node:
        global_nodes.append({'host': host, 'port': port})
    return json.dumps(global_nodes)


def sync_with_nodes():
    '''
    Syncs blocks with node
    '''
    global global_nodes

    # Init connection
    for node in global_nodes:
        try:
            misocoin_cli('init_connection', [global_host, global_port], **node)
        except:
            pass

    # Checks every 15 seconds
    while True:
        # Checks with nodes, syncs with the one with
        # the longest chain
        longest_node = None
        best_height = len(global_blockchain)

        for node in global_nodes:
            # If node['host'] is in black list then continue
            if node['host'] in global_blacklisted_nodes:
                continue

            try:
                node_best_length = misocoin_cli(
                    'get_info', [], **node)['height']

                if node_best_length > best_height:
                    longest_node = node
                    best_height = node_best_length

            except:
                pass

        # Syncs with that node
        if longest_node is not None:
            latest_block_dict = misocoin_cli(
                'get_block', [best_height], **longest_node)
            latest_block = Block.fromJSON(latest_block_dict)

            # Append to latest blockchain
            add_to_blockchain(latest_block)

        time.sleep(10)


def run_misocoin(host='localhost', port=4000, nodes=['localhost:4000'], **kwargs):
    t1 = threading.Thread(target=partial(
        run_simple, threaded=True, request_handler=MisocoinRequestHandler), args=(host, port, misocoin_app))
    t1.daemon = True
    t1.start()

    t2 = threading.Thread(target=sync_with_nodes, args=())
    t2.start()

    t3 = threading.Thread(target=block_management, args=())
    t3.start()    

    t1.join()    
    t2.join()
    t3.join()


if __name__ == '__main__':
    config = list(filter(lambda x: x[0] is '-', sys.argv[1:]))
    config_kwargs = reduce(lambda x, y: {y.split(
        '=')[0][1:]: y.split('=')[1], **x}, config, {})

    # global host and port
    global_host = config_kwargs.get('host', global_host)
    global_port = config_kwargs.get('port', global_port)

    # Get global node and filter out useless values and
    # mush it into the format we want
    global_nodes = config_kwargs.get('nodes', '').split(',')
    global_nodes = list(
        filter(lambda x: (len(x) > 0 and ':' in x and x is not (global_host + ':' + str(global_port))), global_nodes))
    global_nodes = list(map(lambda x: {'host': x.split(
        ':')[0], 'port': x.split(':')[1]}, global_nodes))

    # account private key
    account_priv_key = config_kwargs.get('priv_key', get_new_priv_key())
    account_address = get_address(get_pub_key(account_priv_key))    

    print('** [Welcome] Your misocoin address is {}'.format(account_address))

    run_misocoin(**config_kwargs)

import platform
import psutil
import subprocess
import re


def safe_del(d, key):
    if key in d:
        del d[key]


# Composed with basic coding tools
# hopefully no security risks, too lazy to check


def get_nvidia_gpu_info():
    try:
        import pynvml
    except ImportError:
        print('Warning: pynvml module not installed! ')
        raise ImportError
    pynvml.nvmlInit()
    driver_version = pynvml.nvmlSystemGetDriverVersion()
    cuda_version = "Unknown"
    # Try to get the CUDA runtime version
    try:
        cuda_version_output = subprocess.check_output(['nvcc', '--version']).decode()
        # Parse the output to find the CUDA version
        match = re.search(r'release\s+(\d+\.\d+)', cuda_version_output)
        if match:
            cuda_version = match.group(1)
    except:
        pass

    device_count = pynvml.nvmlDeviceGetCount()
    gpu_info_list = []
    for i in range(device_count):
        handle = pynvml.nvmlDeviceGetHandleByIndex(i)
        name = pynvml.nvmlDeviceGetName(handle)
        memory_info = pynvml.nvmlDeviceGetMemoryInfo(handle)
        memory_total = memory_info.total // (1024 ** 2)  # Convert bytes to MB
        memory_clock = pynvml.nvmlDeviceGetClockInfo(handle, pynvml.NVML_CLOCK_MEM)
        # Get compute capability
        try:
            major, minor = pynvml.nvmlDeviceGetCudaComputeCapability(handle)
            compute_capability = "{}.{}".format(major, minor)
        except:
            compute_capability = "Unknown"
        gpu_info = {
            'name': name,
            'memory': "{} MB".format(memory_total),
            'memory_clock': "{} MHz".format(memory_clock),
            'compute_capability': compute_capability,
            'cuda_driver_version': driver_version,
            'cuda_runtime_version': cuda_version,
        }
        gpu_info_list.append(gpu_info)
    pynvml.nvmlShutdown()
    return gpu_info_list


def get_system_info(print_status = True, include_sensitive_stuff = False):
    if print_status:
        print('Grabbing system information...', end='')

    info = {}
    # Basic platform info
    system = platform.system()
    info['platform'] = system
    info['platform_release'] = platform.release()
    info['platform_version'] = platform.version()
    info['architecture'] = platform.machine()
    info['hostname'] = platform.node()

    if system == 'Windows':
        try:
            import wmi
            c = wmi.WMI()

            # Processor info
            for processor in c.Win32_Processor():
                info['processor'] = {
                    'name': processor.Name.strip(),
                    'cores': processor.NumberOfCores,
                    'logical_cores': processor.NumberOfLogicalProcessors,
                    'speed': "{} MHz".format(processor.MaxClockSpeed)
                }

            # GPU info
            gpu_info_list = []
            for gpu in c.Win32_VideoController():
                gpu_info = {
                    'name': gpu.Name.strip(),
                    'driver_version': gpu.DriverVersion,
                    'video_processor': vp.strip() if (vp := gpu.VideoProcessor) is not None else None,
                    'adapter_ram': "{} MB".format(int(gpu.AdapterRAM) // (1024 ** 2)) if gpu.AdapterRAM else 'Unknown',
                    'adapter_dac_type': adact.strip() if (adact := gpu.AdapterDACType) is not None else None,
                    # 'video_mode_description': gpu.VideoModeDescription.strip(),
                    'manufacturer': ac.strip() if (ac := gpu.AdapterCompatibility) is not None else Noneo,
                }
                gpu_info_list.append(gpu_info)
            info['gpu'] = gpu_info_list

            # Check if GPU is from NVIDIA
            nvidia_present = any(
                'NVIDIA' in gpu['name'] or 'NVIDIA' in gpu.get('manufacturer', '') for gpu in gpu_info_list)

            if nvidia_present:
                # Use pynvml to get more detailed NVIDIA GPU info
                try:
                    nvidia_gpu_info_list = get_nvidia_gpu_info()
                    # Merge or replace existing NVIDIA GPU info
                    for i, gpu in enumerate(gpu_info_list):
                        if 'NVIDIA' in gpu['name'] or 'NVIDIA' in gpu.get('manufacturer', ''):
                            if i < len(nvidia_gpu_info_list):
                                gpu.update(nvidia_gpu_info_list[i])
                except Exception as e:
                    print("Error getting NVIDIA GPU info: {}".format(e))

            # RAM speed
            ram_speeds = [int(mem.Speed) for mem in c.Win32_PhysicalMemory() if mem.Speed is not None]
            if ram_speeds:
                info['ram_speed'] = "{} MHz".format(max(ram_speeds))
            else:
                info['ram_speed'] = "Unknown"
        except ImportError:
            print('Warning: wmi module not installed! ', end='')
            info['processor'] = 'Requires wmi module'
            info['gpu'] = [{'name': 'Requires wmi module', 'adapter_ram': 'Unknown'}]
            info['ram_speed'] = 'Requires wmi module'

    elif system == 'Linux':
        # Processor info
        try:
            lscpu_output = subprocess.check_output('lscpu', shell=True).decode()
            cpu_info = {}
            for line in lscpu_output.split('\n'):
                if line:
                    parts = line.split(':')
                    if len(parts) == 2:
                        key, value = parts
                        cpu_info[key.strip()] = value.strip()
            cores = int(cpu_info.get('Core(s) per socket', '0')) * int(cpu_info.get('Socket(s)', '1'))
            info['processor'] = {
                'name': cpu_info.get('Model name', 'Unknown'),
                'cores': cores,
                'logical_cores': int(cpu_info.get('CPU(s)', '0')),
                'speed': "{} MHz".format(cpu_info.get('CPU MHz', 'Unknown'))
            }
        except subprocess.CalledProcessError:
            info['processor'] = 'Unknown'
            info['processor_details'] = 'Unknown'

        # GPU info
        gpu_info_list = []
        try:
            lshw_output = subprocess.check_output('sudo lshw -C display', shell=True).decode()
            gpu_entries = lshw_output.strip().split('*-display')
            for entry in gpu_entries[1:]:
                gpu_info = {}
                product_match = re.search(r'product:\s*(.+)', entry)
                vendor_match = re.search(r'vendor:\s*(.+)', entry)
                memory_match = re.search(r'size:\s*(.+)', entry)

                gpu_info['name'] = product_match.group(1).strip() if product_match else 'Unknown'
                gpu_info['vendor'] = vendor_match.group(1).strip() if vendor_match else 'Unknown'
                gpu_info['memory'] = memory_match.group(1).strip() if memory_match else 'Unknown'
                gpu_info_list.append(gpu_info)
        except subprocess.CalledProcessError:
            gpu_info_list.append({'name': 'Unknown', 'vendor': 'Unknown', 'memory': 'Unknown'})

        # Check if GPU is from NVIDIA
        nvidia_present = any('NVIDIA' in gpu['vendor'] or 'NVIDIA' in gpu['name'] for gpu in gpu_info_list)
        if nvidia_present:
            try:
                import pynvml
                nvidia_gpu_info_list = get_nvidia_gpu_info()
                # Merge or replace existing NVIDIA GPU info
                for i, gpu in enumerate(gpu_info_list):
                    if 'NVIDIA' in gpu['name'] or 'NVIDIA' in gpu.get('vendor', ''):
                        if i < len(nvidia_gpu_info_list):
                            gpu.update(nvidia_gpu_info_list[i])
            except Exception as e:
                print("Error getting NVIDIA GPU info: {}".format(e))

        info['gpu'] = gpu_info_list

        # RAM speed
        try:
            dmidecode_output = subprocess.check_output("sudo dmidecode -t memory", shell=True).decode()
            ram_speeds = re.findall(r'Speed:\s*(\d+)', dmidecode_output)
            if ram_speeds:
                info['ram_speed'] = "{} MHz".format(max(map(int, ram_speeds)))
            else:
                info['ram_speed'] = "Unknown"
        except subprocess.CalledProcessError:
            info['ram_speed'] = "Unknown"

    # RAM info (common for both)
    total_ram = psutil.virtual_memory().total
    info['ram'] = "{} GB".format(round(total_ram / (1024.0 ** 3)))

    if not include_sensitive_stuff:
        del info['hostname']
        del info['platform_version']

    for gpu in info['gpu']:
        safe_del(gpu, 'video_mode_description')
        if not include_sensitive_stuff:
