def ensure_nltk_resources():
    resources = [
        'punkt', 'averaged_perceptron_tagger', "averaged_perceptron_tagger_eng", 'maxent_ne_chunker',
        'words', 'stopwords', 'wordnet', 'omw-1.4'
    ]

    for resource in resources:
        try:
            nltk.data.find("{}".format(resource))
        except LookupError:
            print("Downloading '{}'...".format(resource))
            nltk.download(resource, quiet=True)

ensure_nltk_resources()

app = Flask(__name__)
app.secret_key = 'kwic_analyzer_secret_key'

def extract_text_from_url(url):
    try:
        headers = {'User-Agent': 'Mozilla/5.0'}
        response = requests.get(url, headers=headers)
        response.raise_for_status()
        soup = BeautifulSoup(response.content, 'html.parser')

        # Remove script and style tags
        for script in soup(["script", "style"]):
            script.extract()

        # Get text content
        text = soup.get_text()

        # Clean up whitespace
        lines = (line.strip() for line in text.splitlines())
        chunks = (phrase.strip() for line in lines for phrase in line.split("  "))
        text = '\n'.join(chunk for chunk in chunks if chunk)

        return text
    except Exception as e:
        print("Error fetching URL: {}".format(e))
        return ""

