                        elif line.strip() and current_category:
                            color_code_map = {
                                'red': '\033[91m',
                                'green': '\033[92m',
                                'yellow': '\033[93m',
                                'blue': '\033[94m',
                                'magenta': '\033[95m',
                                'cyan': '\033[96m'
                            }

                            color_code = color_code_map.get(color, '\033[91m')
                            end_code = '\033[0m'

                            line = line.replace(color_code, '<span class="highlight ' + color + '">').replace(end_code, '</span>')
                            current_lines.append(line)

                    if current_category and current_lines:
                        categories.append({
                            'name': current_category,
                            'lines': current_lines
                        })

                    results = categories
                else:
                    error_message = "No matches found for '{}'. Please try a different search term.".format(search_words)
            else:
                source_name = "Wikipedia article '{}'".format(wiki_topic) if search_mode == 'wikipedia' else "URL '{}'".format(url)
                error_message = "Could not fetch text from {}. Please try a different search.".format(source_name)
                results = []
    except Exception as e:
        error_message = "An error occurred: {}".format(str(e))
        print("Error in processing request: {}".format(e))

    return render_template('index.html', 
                          results=results, 
                          wiki_topic=wiki_topic,
                          url=url,
                          search_mode=search_mode,
                          search_words=search_words,
                          window=window,
                          color=color,
                          language=language,
                          error_message=error_message)

@app.route('/api/kwic', methods=['POST'])
def kwic_api():
