            f = io.StringIO()
            with redirect_stdout(f):
                corpus_b.kwic_grouped_by_pos_and_sorted(corpus_b.text, search_words, window=window, color=color, language=language)

            output = f.getvalue()

            if output.strip():
                categories = []
                current_category = None
                current_lines = []

                for line in output.split('\n'):
                    if line.startswith('<') and line.endswith('>'):
                        if current_category:
                            categories.append({
                                'name': current_category,
                                'lines': current_lines
                            })
                        current_category = line.strip('<>')
                        current_lines = []
                    elif line.strip() and current_category:
                        color_code_map = {
                            'red': '\033[91m',
                            'green': '\033[92m',
                            'yellow': '\033[93m',
                            'blue': '\033[94m',
                            'magenta': '\033[95m',
                            'cyan': '\033[96m'
                        }

                        color_code = color_code_map.get(color, '\033[91m')
                        end_code = '\033[0m'

                        line = line.replace(color_code, '<span class="highlight ' + color + '">').replace(end_code, '</span>')
                        current_lines.append(line)

                if current_category and current_lines:
                    categories.append({
                        'name': current_category,
                        'lines': current_lines
                    })

                return jsonify({"success": True, "results": categories})
            else:
                return jsonify({"success": False, "error": "No matches found for '{}'. Please try a different search term.".format(search_words)})
        else:
            source_name = "Wikipedia article '{}'".format(wiki_topic) if search_mode == 'wikipedia' else "URL '{}'".format(url)
            return jsonify({"success": False, "error": "Could not fetch text from {}. Please try a different search.".format(source_name)})
    except Exception as e:
        return jsonify({"success": False, "error": "An error occurred: {}".format(str(e))})

